#include <iostream>
using namespace std;

int main()
{
    int x, z, m, c, d, f, e, n;
    d = f = e = 0;
    cin >> x >> z;
    n = 1;

    while (n <= 6)
    {
        m = x - n;
        c = z - n;

        if (m < 0)
            m *= -1;
        if (c < 0)
            c *= -1;

        if (c > m)
            d++;
        if (m > c)
            e++;
        if (m == c)
            f++;

        n++;
    }

    cout << d << ' ' << f << ' ' << e << endl;
    return 0;
}

